const SCHEMAS = {
  note_create: {
    properties: { title: {}, body: {} },
    required: ['title', 'body']
  },
  note_get: {
    properties: { note_id: {} },
    required: ['note_id']
  }
};

export async function listTools() {
  return [
    {
      name: 'note_create',
      description: 'Create a note with a required non-empty title and body.',
      inputSchema: {
        type: 'object',
        properties: {
          title: { type: 'string', description: 'The title of the note.' },
          body: { type: 'string', description: 'The body content of the note.' }
        },
        required: ['title', 'body'],
        additionalProperties: false
      }
    },
    {
      name: 'note_get',
      description: 'Retrieve a stored note by its id.',
      inputSchema: {
        type: 'object',
        properties: {
          note_id: { type: 'string', description: 'The id of the note to retrieve.' }
        },
        required: ['note_id'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args) {
  const a = args || {};
  const schema = SCHEMAS[name];
  if (!schema) {
    throw new Error(`unknown tool: ${name}`);
  }
  validateArgs(name, a, schema);

  if (name === 'note_create') {
    const { title, body } = a;
    if (!isNonEmptyString(title)) {
      throw new Error('title is required and must be a non-empty string');
    }
    if (!isNonEmptyString(body)) {
      throw new Error('body is required and must be a non-empty string');
    }
    const id = 'n' + (++counter);
    notes.set(id, { id, title, body });
    return {
      content: [{ type: 'text', text: `Created note ${id}\nTitle: ${title}\nBody: ${body}` }]
    };
  }

  if (name === 'note_get') {
    const { note_id } = a;
    if (!isNonEmptyString(note_id)) {
      throw new Error('note_id is required and must be a non-empty string');
    }
    const note = notes.get(note_id);
    if (!note) {
      throw new Error(`note not found: ${note_id}`);
    }
    return {
      content: [{ type: 'text', text: `Title: ${note.title}\nBody: ${note.body}` }]
    };
  }

  throw new Error(`unknown tool: ${name}`);
}

